#!/usr/bin/env python3
"""Write docs/20261030_FIGURES_STATUS.md from out/MANIFEST.json (counts, determinism, source commits) plus the fixed caveat text."""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
M = json.loads((HERE / "out" / "MANIFEST.json").read_text())
items = M["items"]
rendered = [i for i in items if i["status"] == "rendered"]
pending = [i for i in items if i["status"] == "pending"]

def srcs(i):
    return "; ".join(f"`{Path(s['path']).name}`@{s['commit']}{' (HEAD version used; working tree differs)' if s['dirty'] else ''}" for s in i["sources"]) or "—"

lines = ["# Paper figures and tables — status (2026-10-30)", "",
         "Generated by `research/guangzhou_all_atom/figures_paper/` (`python3 run_all.py [--twice]`, then `python3 make_status.py`). Every plotted number is read from a **committed** artifact; "
         "the script fails if an artifact is uncommitted, and if the working-tree copy differs from HEAD it uses the HEAD version (flagged in the log and metadata). Each figure carries its source paths and commit hashes in the PDF/PNG metadata.", "",
         f"**Assertion log:** {M['assertions']['ok']} OK, {M['assertions']['fail']} FAIL, {M['assertions']['warnings']} notes (artifacts whose working tree differs from HEAD: HEAD version used) (`out/assertion_log.txt`). "
         "Each drawn marker/interval/bar is compared with a fresh re-read of the artifact; cells of heatmaps and forests are compared in bulk.", ""]
d = M.get("determinism")
if d:
    if d["identical"]:
        lines += ["**Determinism:** two full runs produce byte-identical outputs.", ""]
    else:
        lines += ["**Determinism:** two full runs; "
                  f"{len(d['unexplained_differences'])} unexplained differences ({d['unexplained_differences']}); "
                  f"{len(d['source_changed_between_passes'])} outputs differ only because a cited source artifact changed between the passes "
                  f"({', '.join(d['source_changed_between_passes']) or 'none'}).", ""]
lines += ["## Rendered from committed artifacts", "", "| item | title | sources (file@last commit) |", "|---|---|---|"]
lines += [f"| {i['figure']} | {i['title']} | {srcs(i)} |" for i in rendered]
lines += ["", "## Pending placeholders (rendered with a PENDING watermark; contain no numbers)", "", "| item | waits for |", "|---|---|"]
lines += [f"| {i['figure']} | {i['caption'].replace('PENDING: waits for ', '')} |" for i in pending]
lines += ["", "Partial items: **F5** (controls; GBM variants only — hollow markers where < 8 paired seeds), **F11** (coverage; the knowledge × property × substructure matrix is F11b, pending), "
          "**T6** (model comparison; auto-fills from `l7_aggregate.json`, every other model is PENDING). Tables written to `out/tables/*.md|csv`.", "",
          "## Not generated by script (text tables assembled from documents, no machine-readable artifact)",
          "T2 audit/positive-control log, T3 models compared (needs the model survey and IH-LM provenance), T4 decision rules, T8 knowledge bases audited, T9 prior-art risk, supplementary tables S1–S5 (hash tables can be generated from `FROZEN_HASHES*.json` once the manuscript fixes the format).", "",
          "## Observations made while building (for the manuscript owner)",
          "- F2(b): the median within-group label range is 0.855 log units; the analysis documents state 0.86 (rounding). The figure prints 0.855; the assertion allows a 0.006 tolerance to the documented 0.86.",
          "- F8: the label-free N-methyl rule appears only in the grouped-by-flat-structure panel (the artifact has no leave-labs-out row for it); no stratum is flagged `small` in the artifact, so no cell is hatched.",
          "- FCV: strata CSVs have no overall rows; overall Spearman is recomputed from `cv_preds.csv.gz` with a source-cluster bootstrap (B=2000, seed 0) and checked against the figures quoted in the analysis document (0.31/0.30/0.26 leave-labs-out).",
          "- F3: analysis M3 has validity-gate results only (arms not scored; the analysis is invalid). Analyses I, M, M2 and M3 all fail at least one primary control, so verdicts apply only under the control-adjusted rule.",
          "- FH4b: the control C3 (Morgan leave-fold-out) is drawn at every k; it exceeds 0.5 at every k.",
          "- F5/T6: drawn from the aggregate regenerated after the key-collision fix (keys `gbm_aware`, `gbm_blind`, `gbm_physchem`; 10 paired seeds in every regime shown); the earlier note that regime B had 2 seeds was a symptom of the collision and is obsolete. `chemberta` has 3 seeds in A and B (exploratory).",
          "- T1: binding-table, stability, conformational and renal profiles are PENDING (no machine-readable profile artifact).",
          "- Source commit hashes are the last commit touching each file; regenerate after any artifact changes (the manifest records them).", ""]
(ROOT / "docs" / "20261030_FIGURES_STATUS.md").write_text("\n".join(lines))
print("wrote docs/20261030_FIGURES_STATUS.md")
